messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #111; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- 1. Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x202025);
        scene.fog = new THREE.Fog(0x202025, 10, 30);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 2, 8);
        camera.lookAt(0, 1, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        document.body.appendChild(renderer.domElement);

        // --- 2. Lights ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(-5, 10, 5);
        dirLight.castShadow = true;
        scene.add(dirLight);

        // --- 3. Character Construction ---
        const material = new THREE.MeshStandardMaterial({ color: 0x00ffcc, roughness: 0.3 });
        const darkMaterial = new THREE.MeshStandardMaterial({ color: 0x333333 });

        const character = new THREE.Group();

        // Torso
        const torso = new THREE.Mesh(new THREE.BoxGeometry(0.6, 1.0, 0.4), material);
        torso.position.y = 1.6;
        torso.castShadow = true;
        character.add(torso);

        // Head
        const head = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.4, 0.35), material);
        head.position.y = 2.35;
        head.castShadow = true;
        character.add(head);

        // Joints (Pivots)
        const shoulderL = new THREE.Group(); shoulderL.position.set(-0.35, 1.9, 0); character.add(shoulderL);
        const shoulderR = new THREE.Group(); shoulderR.position.set(0.35, 1.9, 0); character.add(shoulderR);
        const hipL = new THREE.Group(); hipL.position.set(-0.2, 1.1, 0); character.add(hipL);
        const hipR = new THREE.Group(); hipR.position.set(0.2, 1.1, 0); character.add(hipR);

        // Arms (Meshes are offset so pivot is at top)
        const upperArmGeo = new THREE.BoxGeometry(0.15, 0.5, 0.15);
        const lowerArmGeo = new THREE.BoxGeometry(0.12, 0.45, 0.12);

        const armL = new THREE.Mesh(upperArmGeo, material); armL.position.y = -0.25; shoulderL.add(armL);
        const armR = new THREE.Mesh(upperArmGeo, material); armR.position.y = -0.25; shoulderR.add(armR);

        // Legs
        const upperLegGeo = new THREE.BoxGeometry(0.2, 0.5, 0.2);
        const lowerLegGeo = new THREE.BoxGeometry(0.15, 0.45, 0.15);

        const legL = new THREE.Mesh(upperLegGeo, material); legL.position.y = -0.25; hipL.add(legL);
        const legR = new THREE.Mesh(upperLegGeo, material); legR.position.y = -0.25; hipR.add(legR);

        // --- 4. Treadmill ---
        const beltGeo = new THREE.PlaneGeometry(4, 1.5);
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x444444, side: THREE.DoubleSide });
        const belt = new THREE.Mesh(beltGeo, beltMat);
        belt.rotation.x = -Math.PI / 2;
        belt.receiveShadow = true;
        scene.add(belt);

        const railGeo = new THREE.BoxGeometry(4.2, 0.2, 0.1);
        const railL = new THREE.Mesh(railGeo, darkMaterial); railL.position.set(0, 0.1, 0.75);
        const railR = new THREE.Mesh(railGeo, darkMaterial); railR.position.set(0, 0.1, -0.75);
        scene.add(railL); scene.add(railR);

        // --- 5. Animation Logic ---
        const clock = new THREE.Clock();
        const CYCLE_LENGTH = 10; // 10 seconds

        // State: 0-2s Idle, 2-5s Walk, 5-8s Run, 8-10s Idle

        function easeInOutCubic(t) {
            return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
        }

        function animate() {
            requestAnimationFrame(animate);

            const time = clock.getElapsedTime();
            const cycleTime = time % CYCLE_LENGTH;

            // 1. Determine Mode
            let mode = 'idle';
            let progress = 0; // 0 to 1 within the phase

            if (cycleTime < 2) {
                mode = 'idle';
                progress = 0;
            } else if (cycleTime < 5) {
                mode = 'walk';
                progress = (cycleTime - 2) / 3;
            } else if (cycleTime < 8) {
                mode = 'run';
                progress = (cycleTime - 5) / 3;
            } else {
                mode = 'idle';
                progress = 0;
            }

            // 2. Apply Animation
            // Reset to base
            character.position.y = 0;
            torso.rotation.x = 0; // 0 is upright

            if (mode === 'idle') {
                // Lerp back to idle
                shoulderL.rotation.x = 0; shoulderR.rotation.x = 0;
                hipL.rotation.x = 0; hipR.rotation.x = 0;
                belt.material.map = null; // visual reset
            } 
            else if (mode === 'walk') {
                // Smooth entry
                const ease = easeInOutCubic(progress);
                const walkFreq = 10;
                const t = time * walkFreq;

                // Bobbing
                character.position.y = Math.abs(Math.sin(t)) * 0.05;

                // Limbs
                shoulderL.rotation.x = Math.sin(t) * 0.5;
                shoulderR.rotation.x = Math.sin(t + Math.PI) * 0.5;
                hipL.rotation.x = Math.sin(t + Math.PI) * 0.5;
                hipR.rotation.x = Math.sin(t) * 0.5;

                // Belt move
                belt.position.z = (time * 1) % 4; 
            } 
            else if (mode === 'run') {
                // Smooth entry
                const ease = easeInOutCubic(progress);
                const runFreq = 18;
                const t = time * runFreq;

                // Lean
                torso.rotation.x = -0.2;

                // Bobbing (higher)
                character.position.y = Math.abs(Math.sin(t)) * 0.15;

                // Limbs (wider range, faster)
                shoulderL.rotation.x = Math.sin(t) * 1.2;
                shoulderR.rotation.x = Math.sin(t + Math.PI) * 1.2;
                hipL.rotation.x = Math.sin(t + Math.PI) * 1.0;
                hipR.rotation.x = Math.sin(t) * 1.0;

                // Belt move
                belt.position.z = (time * 3) % 4;
            }

            renderer.render(scene, camera);
        }

        // Handle resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
